def _windows_debug_console_requested() -> bool:
    """Read the saved next-launch choice before the expensive Qt/vision imports.

    Settings normally live in %APPDATA%/Freehand. Use the old in-project
    settings file only on first launch, before user_paths migrates it.
    """
    roaming = Path(os.environ.get("APPDATA") or (Path.home() / "AppData" / "Roaming"))
    saved = roaming / "Freehand" / "ui_settings.json"
    if not saved.is_file():
        saved = Path(__file__).resolve().parent / "ui_settings.json"
    try:
        return json.loads(saved.read_text(encoding="utf-8")).get("debug_console") is True
    except (OSError, ValueError, TypeError, AttributeError):
        return False


def _configure_windows_console_on_startup() -> None:
    """Hide the Windows CMD console by default; show it in debugging mode.

    Hide/show, rather than FreeConsole(), preserves stdout/stderr and the
    original terminal so switching the setting only needs a normal restart.
    Nothing here affects Linux, and failure never prevents Freehand starting.
    """
    if sys.platform != "win32":
        return
    try:
        from ctypes import wintypes as _wintypes
        kernel = ctypes.WinDLL("kernel32", use_last_error=True)
        user = ctypes.WinDLL("user32", use_last_error=True)
        kernel.GetConsoleWindow.restype = _wintypes.HWND
        user.ShowWindow.argtypes = (_wintypes.HWND, ctypes.c_int)
        user.ShowWindow.restype = ctypes.c_bool
        show_debug = _windows_debug_console_requested()
        hwnd = kernel.GetConsoleWindow()
        if not hwnd and show_debug:
            # Also support a windowed/pythonw launcher: create a console on
            # the next run only when the user explicitly enables debugging.
            if kernel.AllocConsole():
                hwnd = kernel.GetConsoleWindow()
                if sys.stdout is None:
                    sys.stdout = open("CONOUT$", "w", encoding="utf-8", buffering=1)
                if sys.stderr is None:
                    sys.stderr = open("CONOUT$", "w", encoding="utf-8", buffering=1)
        if hwnd:
            user.ShowWindow(hwnd, 5 if show_debug else 0)  # SW_SHOW / SW_HIDE
    except (OSError, AttributeError, ValueError):
        pass


# Run this before OpenCV, MediaPipe and Qt load, avoiding an unnecessarily
# long visible CMD window while heavy modules initialise.
if __name__ == "__main__" and sys.platform == "win32":
    _configure_windows_console_on_startup()

# Show the branded splash BEFORE importing the heavy camera, speech and scene
# modules. The same QApplication will later run the real Freehand event loop.
# This is deliberately a static Qt splash, not a separate Python process or
# launcher script: no additional requirements and no window-flashing restart.
_FREEHAND_BOOT_APP = None
_FREEHAND_BOOT_SPLASH = None
_FREEHAND_SPLASH_EXIT_ANIMATION = None
_FREEHAND_SPLASH_SHOWN_AT = 0.0

# Keep the supplied Freehand_logo.png completely unchanged. These durations
# animate only the native splash window's alpha, not the source image.
_FREEHAND_SPLASH_FADE_IN_MS = 480
_FREEHAND_SPLASH_FADE_OUT_MS = 460


def _show_freehand_startup_splash():
    global _FREEHAND_BOOT_APP, _FREEHAND_BOOT_SPLASH, _FREEHAND_SPLASH_SHOWN_AT
    from PySide6.QtCore import (Qt as _Qt, QPropertyAnimation as _QPropertyAnimation,
                                QEasingCurve as _QEasingCurve, QEventLoop as _QEventLoop,
                                QTimer as _QTimer)
    from PySide6.QtGui import QPixmap as _QPixmap
    from PySide6.QtWidgets import QApplication as _QApplication, QSplashScreen as _QSplashScreen

    app = _QApplication.instance()
    if app is None:
        app = _QApplication(sys.argv)
    app.setQuitOnLastWindowClosed(False)
    _FREEHAND_BOOT_APP = app

    logo = Path(__file__).resolve().parent / "Freehand_logo.png"
    if not logo.is_file():
        return
    pixmap = _QPixmap(str(logo))
    if pixmap.isNull():
        print("Could not load startup splash:", logo, flush=True)
        return
    screen = _QApplication.primaryScreen()
    if screen is not None:
        available = screen.availableGeometry()
        max_width = max(280, min(760, int(available.width() * 0.62)))
        max_height = max(180, min(480, int(available.height() * 0.60)))
        pixmap = pixmap.scaled(max_width, max_height, _Qt.KeepAspectRatio,
                               _Qt.SmoothTransformation)
    splash = _QSplashScreen(pixmap)
    splash.setWindowFlags(splash.windowFlags() |
                          _Qt.FramelessWindowHint | _Qt.WindowStaysOnTopHint)
    splash.setAttribute(_Qt.WA_TransparentForMouseEvents, True)
    splash.setAttribute(_Qt.WA_ShowWithoutActivating, True)
    if screen is not None:
        screen_rect = screen.availableGeometry()
        splash.move(screen_rect.center().x() - splash.width() // 2,
                    screen_rect.center().y() - splash.height() // 2)
    # Start transparent before mapping the window, preventing a single-frame
    # flash of the full-opacity image on Qt/Windows. The picture itself is never
    # transformed, recoloured, regenerated or rewritten.
    splash.setWindowOpacity(0.0)
    _FREEHAND_BOOT_SPLASH = splash
    splash.show()
    splash.raise_()
    _FREEHAND_SPLASH_SHOWN_AT = time.monotonic()

    fade_in = _QPropertyAnimation(splash, b"windowOpacity", splash)
    fade_in.setDuration(_FREEHAND_SPLASH_FADE_IN_MS)
    fade_in.setStartValue(0.0)
    fade_in.setEndValue(1.0)
    fade_in.setEasingCurve(_QEasingCurve.OutCubic)
    # Startup immediately imports CPU-heavy modules and may synchronously
    # download the vision model before QApplication.exec() begins. A normal
    # asynchronous animation would freeze on the first transparent frame.
    # Run this short nested Qt loop first so the fade is genuinely visible.
    fade_loop = _QEventLoop()
    fade_in.finished.connect(fade_loop.quit)
    _QTimer.singleShot(_FREEHAND_SPLASH_FADE_IN_MS + 250, fade_loop.quit)
    fade_in.start()
    fade_loop.exec()
    splash.setWindowOpacity(1.0)
    app.processEvents()


if __name__ == "__main__":
    _show_freehand_startup_splash()

